import{_ as n,c as a,a2 as p,o as l}from"./chunks/framework.Bzjhwp8w.js";const u=JSON.parse('{"title":"全局变量","description":"全局变量","frontmatter":{"title":"全局变量","description":"全局变量","layout":"doc"},"headers":[],"relativePath":"langflow/configuration-global-variables.md","filePath":"langflow/configuration-global-variables.md"}'),e={name:"langflow/configuration-global-variables.md"};function i(r,s,t,o,c,b){return l(),a("div",null,s[0]||(s[0]=[p('<h1 id="全局变量" tabindex="-1">全局变量 <a class="header-anchor" href="#全局变量" aria-label="Permalink to &quot;全局变量&quot;">​</a></h1><p>全局变量允许您在项目中存储和重用通用的输入值和凭证。您可以在任何显示<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-globe" aria-label="Globe"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"></path><path d="M2 12h20"></path></svg><strong>Globe</strong>图标的文本输入字段中使用全局变量。</p><p>Langflow 将全局变量存储在其内部数据库中，并使用密钥加密这些值。</p><h2 id="创建全局变量" tabindex="-1">创建全局变量 <a class="header-anchor" href="#创建全局变量" aria-label="Permalink to &quot;创建全局变量&quot;">​</a></h2><ol><li><p>在 Langflow 用户界面中，点击你的个人资料图标，然后选择 <strong>设置</strong>。</p></li><li><p>点击 <strong>全局变量</strong>。</p></li><li><p>点击 <strong>新增</strong>。</p></li><li><p>在 <strong>创建变量</strong> 对话框中，在 <strong>变量名称</strong> 字段中输入你的变量名称。</p></li><li><p>可选：为你的全局变量选择一个 <strong>类型</strong>。可用的类型有 <strong>通用</strong>（默认）和 <strong>凭证</strong>。</p><p>不管你选择哪种 <strong>类型</strong>，Langflow 都会加密全局变量的 <strong>值</strong>。</p></li><li><p>输入你的全局变量的 <strong>值</strong>。</p></li><li><p>可选：使用 <strong>应用到字段</strong> 菜单，选择一个或多个希望 Langflow 自动应用你的全局变量的字段。例如，如果你选择了 <strong>OpenAI API Key</strong>，Langflow 会自动将变量应用到任何 <strong>OpenAI API Key</strong> 字段。</p></li><li><p>点击 <strong>保存变量</strong>。</p></li></ol><p>你现在可以从显示 🌐 图标的任何文本输入字段中选择你的全局变量。</p><blockquote><p><strong>info</strong></p><p>由于值是加密的，你无法查看全局变量的实际值。在 <strong>设置 &gt; 全局变量</strong> 中，<strong>值</strong> 列会显示 <strong>通用</strong> 类型变量的加密哈希，对于 <strong>凭证</strong> 类型变量则不显示任何内容。</p></blockquote><h2 id="编辑全局变量" tabindex="-1">编辑全局变量 <a class="header-anchor" href="#编辑全局变量" aria-label="Permalink to &quot;编辑全局变量&quot;">​</a></h2><ol><li>在 Langflow 用户界面中，点击你的个人资料图标，然后选择 <strong>设置</strong>。</li><li>点击 <strong>全局变量</strong>。</li><li>点击你想要编辑的全局变量。</li><li>在 <strong>更新变量</strong> 对话框中，你可以编辑以下字段：<strong>变量名称</strong>、<strong>值</strong>和 <strong>应用于字段</strong>。</li><li>点击 <strong>更新变量</strong>。</li></ol><h2 id="删除全局变量" tabindex="-1">删除全局变量 <a class="header-anchor" href="#删除全局变量" aria-label="Permalink to &quot;删除全局变量&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>删除全局变量会永久删除现有项目中对该变量的任何引用。</p></div><ol><li>在 Langflow UI 中，点击你的个人资料图标，然后选择 <strong>设置</strong>。</li><li>点击 <strong>全局变量</strong>。</li><li>勾选你想要删除的全局变量旁边的复选框。</li><li>点击删除图标。</li></ol><p>全局变量以及对它的所有现有引用都会被删除。</p><h2 id="添加来自环境的全局变量" tabindex="-1">添加来自环境的全局变量 <a class="header-anchor" href="#添加来自环境的全局变量" aria-label="Permalink to &quot;添加来自环境的全局变量&quot;">​</a></h2><h3 id="自定义环境变量" tabindex="-1">自定义环境变量 <a class="header-anchor" href="#自定义环境变量" aria-label="Permalink to &quot;自定义环境变量&quot;">​</a></h3><p>您可以使用 <code>LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT</code> 环境变量从运行时环境中获取全局变量。</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 本地 Docker</span></span>\n<span class="line"><span>- Local</span></span>\n<span class="line"><span>- Docker</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>如果您在本地安装了 Langflow，您必须在 `.env` 文件中定义 `LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT` 环境变量。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>1. 创建一个 `.env` 文件，并使用您喜欢的编辑器打开它。</span></span>\n<span class="line"><span>2. 如下添加 `LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT` 环境变量：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>   ```plaintext</span></span>\n<span class="line"><span>   LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT=VARIABLE1,VARIABLE2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>将 <code>VARIABLE1,VARIABLE2</code> 替换为要让 Langflow 从环境中获取的变量列表，变量之间用逗号隔开，不要有空格。例如：<code>my_key,some_string</code>。</p><ol start="3"><li><p>保存并关闭文件。</p></li><li><p>使用 <code>.env</code> 文件启动 Langflow：</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VARIABLE1=&quot;VALUE1&quot; VARIABLE2=&quot;VALUE2&quot; python -m langflow run --env-file .env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p><strong>注意</strong><br> 在此示例中，环境变量 (<code>VARIABLE1=&quot;VALUE1&quot;</code> 和 <code>VARIABLE2=&quot;VALUE2&quot;</code>) 被添加到启动命令前。这是一种在命令行中向 Python 暴露环境变量的基本方法，仅供示例。请确保以适合您环境的最佳方式将环境变量暴露给 Langflow。</p></blockquote></li><li><p>确认 Langflow 成功从环境中获取了全局变量。</p><ol><li>在 Langflow 界面中，点击您的个人资料图标，然后选择 <strong>设置</strong>。</li><li>点击 <strong>全局变量</strong>。</li></ol><p>环境变量会在 <strong>全局变量</strong> 列表中显示。</p></li></ol><p>如果您使用 Docker，可以直接从命令行或 <code>.env</code> 文件传递 <code>LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT</code>。</p><p>要从命令行直接传递 <code>LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT</code>：</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker run -it --rm \\</span></span>\n<span class="line"><span>    -p 7860:7860 \\</span></span>\n<span class="line"><span>    -e LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT=&quot;VARIABLE1,VARIABLE2&quot; \\</span></span>\n<span class="line"><span>    -e VARIABLE1=&quot;VALUE1&quot; \\</span></span>\n<span class="line"><span>    -e VARIABLE2=&quot;VALUE2&quot; \\</span></span>\n<span class="line"><span>    langflowai/langflow:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>要从 <code>.env</code> 文件传递 <code>LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT</code>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7860:7860</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VARIABLE1=&quot;VALUE1&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VARIABLE2=&quot;VALUE2&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    langflowai/langflow:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>在从环境添加全局变量时，存在以下限制：</p><ul><li>你只能从环境中获取<strong>名称</strong>和<strong>值</strong>。要添加其他参数，例如<strong>应用于字段</strong>参数，必须在 Langflow UI 中编辑全局变量。</li><li>你从环境中添加的全局变量总是具有<strong>凭据</strong>类型。</li></ul></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>::: tip</span></span>\n<span class="line"><span>如果您想明确阻止 Langflow 从环境中获取全局变量，请在您的 `.env` 文件中将 `LANGFLOW_STORE_ENVIRONMENT_VARIABLES` 设置为 `false`：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```plaintext</span></span>\n<span class="line"><span>LANGFLOW_STORE_ENVIRONMENT_VARIABLES=false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>:::</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>\n<span class="line"><span>### 默认环境变量</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Langflow 会自动检测并将某些环境变量转换为 **Credential（凭证）** 类型的全局变量，这些变量被应用于需要它们的组件的特定字段。目前支持以下变量：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- `OPENAI_API_KEY`</span></span>\n<span class="line"><span>- `ANTHROPIC_API_KEY`</span></span>\n<span class="line"><span>- `GOOGLE_API_KEY`</span></span>\n<span class="line"><span>- `COHERE_API_KEY`</span></span>\n<span class="line"><span>- `GROQ_API_KEY`</span></span>\n<span class="line"><span>- `HUGGINGFACEHUB_API_TOKEN`</span></span>\n<span class="line"><span>- `SEARCHAPI_API_KEY`</span></span>\n<span class="line"><span>- `SERPAPI_API_KEY`</span></span>\n<span class="line"><span>- `AZURE_OPENAI_API_KEY`</span></span>\n<span class="line"><span>- `AZURE_OPENAI_API_VERSION`</span></span>\n<span class="line"><span>- `AZURE_OPENAI_API_INSTANCE_NAME`</span></span>\n<span class="line"><span>- `AZURE_OPENAI_API_DEPLOYMENT_NAME`</span></span>\n<span class="line"><span>- `AZURE_OPENAI_API_EMBEDDINGS_DEPLOYMENT_NAME`</span></span>\n<span class="line"><span>- `PINECONE_API_KEY`</span></span>\n<span class="line"><span>- `ASTRA_DB_APPLICATION_TOKEN`</span></span>\n<span class="line"><span>- `ASTRA_DB_API_ENDPOINT`</span></span>\n<span class="line"><span>- `UPSTASH_VECTOR_REST_URL`</span></span>\n<span class="line"><span>- `UPSTASH_VECTOR_REST_TOKEN`</span></span>\n<span class="line"><span>- `VECTARA_CUSTOMER_ID`</span></span>\n<span class="line"><span>- `VECTARA_CORPUS_ID`</span></span>\n<span class="line"><span>- `VECTARA_API_KEY`</span></span>\n<span class="line"><span>- `AWS_ACCESS_KEY_ID`</span></span>\n<span class="line"><span>- `AWS_SECRET_ACCESS_KEY`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>关于其他环境变量及其使用的信息，请参见 [环境变量](URL)。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 安全最佳实践</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>有关保护全局变量和其他敏感数据的信息，请参阅[安全最佳实践](/configuration-security-best-practices)。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br></div></div>',29)]))}const g=n(e,[["render",i]]);export{u as __pageData,g as default};
